    static void cancelVisuals(View view){if(view==null)return;view.animate().cancel();view.setScaleX(1);view.setScaleY(1);view.setTranslationY(0);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)cancelVisuals(group.getChildAt(i));}}
