    void focusable(View v){v.setId(View.generateViewId());v.setFocusable(true);v.setFocusableInTouchMode(true);StateListDrawable state=new StateListDrawable();state.addState(new int[]{android.R.attr.state_focused},surface(true));state.addState(new int[]{},surface(false));v.setBackground(state);v.setOnFocusChangeListener((a,f)->{if(f&&a.getTag() instanceof String){lastFocus=(String)a.getTag();if(lastFocus.contains(".")){if(contextName!=null)contextName.setText(label(lastFocus));if(backdrop!=null)backdrop.select(lastFocus);}}a.animate().cancel();boolean animate=AuraTheme.level(this)>0 && getPreferences(0).getBoolean("animateFocus",true) && a.getParent() instanceof FrameLayout && !transferringLibraryFocus && (library==null||library.getVisibility()!=View.VISIBLE);int level=AuraTheme.level(this);boolean floating=preset().equals("immersive")&&favoritesViews.contains(a);float factor=f&&animate?(level==1?1.025f:level==2?1.05f:1.065f):1f;float lift=f&&animate&&floating?-px(level==1?2:level==2?4:6):0;if(animate)a.animate().scaleX(factor).scaleY(factor).translationY(lift).setDuration(level==1?140:level==2?190:220).start();else{a.setScaleX(factor);a.setScaleY(factor);a.setTranslationY(0);}a.setElevation(level==0?0:px(floating?5+(f?level*2:0):f?level*2:2));});}
