    ArrayList<String> favoritePackages(){String raw=getPreferences(0).getString("favorites",String.join(",",initial));ArrayList<String> result=new ArrayList<>();for(String p:raw.split(",")){if(launchIntent(p)!=null)result.add(p);}return result;}
    Intent launchIntent(String p){PackageManager pm=getPackageManager();Intent i=pm.getLeanbackLaunchIntentForPackage(p);return i!=null?i:pm.getLaunchIntentForPackage(p);}
    String label(String p){switch(p){case "com.tcl.partnercustomizer":return "TCL Channel";case "com.tcl.channelplus":return "TCL Channel";case "com.netflix.ninja":return "Netflix";case "com.google.android.youtube.tv":return "YouTube";case "com.amazon.amazonvideo.livingroom":return "Prime Video";case "com.disney.disneyplus":return "Disney+";case "com.wbd.stream":return "Max";case "com.spotify.tv.android":return "Spotify";}String cached=labelsCache.get(p);if(cached!=null)return cached;int labelGeneration=packageGeneration;try{String name=getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(p,0)).toString();if(name.trim().isEmpty())name=p;if(labelGeneration==packageGeneration)labelsCache.put(p,name);return name;}catch(Exception e){return p;}}
    String preset(){String value=getPreferences(0).getString("preset","modern");return DisplayOptions.valid("preset",value)?value:"modern";}
