    void showAbout(){Dialog d=panel("Velira TV");LinearLayout b=body(d);String version="";try{version=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){}TextView info=text("Versión "+version+" · Vista previa\n\nUn inicio tranquilo, sin anuncios propios. Internet para fondos, vídeos de Ambiente y juegos web que tú abras.\n\nDispositivo de referencia: TCL 50C645. Los ajustes de imagen y sonido pertenecen al televisor.",15,INK);b.addView(info,new LinearLayout.LayoutParams(-1,px(205)));entry(b,"Volver al centro de control",this::showSettings);b.getChildAt(1).requestFocus();}
    void showApps(boolean edit){if(!edit){showLibrary();return;}Dialog d=panel(preset().equals("classic")?"Favoritas · hasta seis en Inicio":preset().equals("immersive")?"Favoritas · fila inmersiva":"Favoritas · hasta seis en Inicio");LinearLayout b=body(d);if(appCache!=null){populateApps(d,b,new ArrayList<>(appCache),edit);return;}b.addView(text("Cargando aplicaciones…",14,MUTED));final int request=packageGeneration;loader.execute(()->{ArrayList<String> found=apps();handler.post(()->{if(!alive||request!=packageGeneration)return;appCache=found;if(activeDialog==d&&d.isShowing()){b.removeAllViews();populateApps(d,b,found,edit);}});});}
    void populateApps(Dialog d,LinearLayout b,ArrayList<String> packages,boolean edit){ArrayList<String> selected=favoritePackages();
      if(edit)entry(b,"Guardar y volver",()->{getPreferences(0).edit().putString("favorites",String.join(",",selected)).apply();d.dismiss();render();ticker.run();});
      for(String p:packages){
        if(edit){CheckBox check=new CheckBox(this);check.setText(label(p));check.setTextColor(INK);check.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,px(15));check.setChecked(selected.contains(p));check.setPadding(px(8),0,0,0);check.setButtonTintList(android.content.res.ColorStateList.valueOf(GOLD));check.setOnCheckedChangeListener((v,on)->{if(on){if(selected.size()>=6){check.setChecked(false);Toast.makeText(this,"Elige hasta seis favoritas",0).show();}else selected.add(p);}else selected.remove(p);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,px(43));b.addView(check,lp);
        }else entry(b,label(p),()->{d.dismiss();launch(p);});
      }if(b.getChildCount()>0)b.getChildAt(0).requestFocus();
    }
    void restoreFocus(){View found=lastFocus.isEmpty()?null:root.findViewWithTag(lastFocus);if(found==null)found=favoritesViews.get(0);found.requestFocus();}
