    void showLibrary(){transferringLibraryFocus=true;try{if(library==null||library.getVisibility()!=View.VISIBLE)libraryReturnFocus=lastFocus;closePanel();if(library==null){library=new AppLibraryView(this);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,px(354),Gravity.BOTTOM);lp.leftMargin=px(24);lp.rightMargin=px(24);lp.bottomMargin=px(12);root.addView(library,lp);}if(root.getChildAt(root.getChildCount()-1)!=library)library.bringToFront();library.open();}finally{transferringLibraryFocus=false;}}
